dashboard.definition:
{
    "title": "Switch Syslog & Telemetry",
    "description": "Switch syslog (cisco:ios) and gNMI telemetry (cisco:gnmi)",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        },
        "input_device": {
            "type": "input.dropdown",
            "title": "Device",
            "dataSources": {
                "primary": "ds_devices"
            },
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "device",
                "defaultValue": "*"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All devices"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"host\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"host\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "device": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_devices": {
            "type": "ds.search",
            "options": {
                "query": "| tstats count where index=demo_cisco_catalyst sourcetype IN (\"cisco:ios\", \"cisco:gnmi\") by host | fields host",
                "enableSmartSources": true
            },
            "name": "Switches"
        },
        "ds_sys": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:gnmi\" subscription=system\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| bin _time span=1m\n| stats latest(cpu_one_minute) as cpu latest(memory_used_pct) as mem latest(interfaces_physical) as physical latest(interfaces_oper_up) as oper_up latest(interfaces_admin_down) as admin_down latest(role) as role latest(platform) as platform latest(sw_site) as sw_site by _time host",
                "enableSmartSources": true
            },
            "name": "gNMI system (1 min)"
        },
        "ds_k_admin": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sys",
                "query": "| stats latest(admin_down) as v by host | stats sum(v) as \"Admin down\""
            }
        },
        "ds_k_stale": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sys",
                "query": "| stats max(_time) as last by host | where last < now() - 300 | stats count as Stale"
            }
        },
        "ds_k_cpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sys",
                "query": "| timechart span=1m avg(cpu) as CPU"
            }
        },
        "ds_rings": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sys",
                "query": "| stats avg(cpu) as value by sw_site\n| eval name=sw_site, value=round(value, 1), unit=\"%\", warn=60, crit=80, better=\"lower\", key=sw_site\n| table name value unit warn crit better key"
            }
        },
        "ds_oper": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sys",
                "query": "| timechart span=1m limit=0 max(oper_up) by host"
            }
        },
        "ds_status": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_sys",
                "query": "| stats max(_time) as last latest(sw_site) as Site latest(role) as Role latest(platform) as Platform latest(physical) as Physical latest(oper_up) as \"Oper up\" latest(admin_down) as \"Admin down\" latest(cpu) as \"CPU %\" latest(mem) as \"Memory %\" by host\n| eval \"Sample age s\"=round(now() - last), \"CPU %\"=round('CPU %', 1), \"Memory %\"=round('Memory %', 1)\n| sort Site Role host\n| table Site host Role Platform Physical \"Oper up\" \"Admin down\" \"CPU %\" \"Memory %\" \"Sample age s\"\n| rename host as Switch"
            }
        },
        "ds_tput": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:gnmi\" subscription=interfaces\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| eval mbps=(in_bps + out_bps) / 1000000\n| bin _time span=1m\n| stats sum(mbps) as mbps by _time host\n| timechart span=1m limit=0 max(mbps) by host",
                "enableSmartSources": true
            },
            "name": "Throughput per switch"
        },
        "ds_ifdown": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:gnmi\" subscription=interfaces\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| stats latest(_time) as t latest(admin_status) as admin latest(oper_status) as oper latest(description) as description latest(speed_mbps) as speed by host interface\n| where oper!=\"UP\" OR admin!=\"UP\"\n| eval Time=strftime(t, \"%H:%M:%S\")\n| table Time host interface description admin oper speed\n| rename host as Switch interface as Interface description as Description admin as Admin oper as Oper speed as \"Speed Mbit/s\"",
                "enableSmartSources": true
            },
            "name": "Interfaces not up"
        },
        "ds_ios": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:ios\"\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| eval msg=facility.\"-\".severity.\"-\".mnemonic, link=if(match(_raw, \"LINK-|LINEPROTO-\"), 1, 0), cfg=if(mnemonic=\"CFGLOG_LOGGEDCMD\", 1, 0)\n| bin _time span=5m\n| stats count sum(link) as link sum(cfg) as cfg dc(user) as users by _time host msg",
                "enableSmartSources": true
            },
            "name": "Syslog (5 min)"
        },
        "ds_k_syslog": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ios",
                "query": "| timechart span=5m sum(count) as Syslog"
            }
        },
        "ds_k_cfg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ios",
                "query": "| timechart span=5m sum(cfg) as Commands"
            }
        },
        "ds_heat_msg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ios",
                "query": "| timechart span=5m limit=15 useother=f sum(count) by msg"
            }
        },
        "ds_link": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ios",
                "query": "| where link > 0 | timechart span=5m limit=0 sum(link) by host"
            }
        },
        "ds_audit": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:ios\" (\"CLI_AUDIT\" OR \"CFGLOG_LOGGEDCMD\" OR \"CONFIG_I\")\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| eval mode=case(mnemonic=\"CFGLOG_LOGGEDCMD\", \"config\", mnemonic=\"CONFIG_I\", \"config end\", true(), \"exec\"), command=coalesce(command, message_text), Time=strftime(_time, \"%H:%M:%S\")\n| head 100\n| table Time host user src mode command\n| rename host as Switch user as User src as Source mode as Mode command as Command",
                "enableSmartSources": true
            },
            "name": "Command audit"
        },
        "ds_sessions": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:ios\" (\"LOGIN_SUCCESS\" OR \"LOGIN_FAILED\" OR \"CLI_AUDIT\" OR \"CFGLOG_LOGGEDCMD\")\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| stats sum(eval(if(mnemonic=\"LOGIN_SUCCESS\", 1, 0))) as Logins sum(eval(if(mnemonic=\"LOGIN_FAILED\", 1, 0))) as \"Failed logins\" sum(eval(if(mnemonic=\"CFGLOG_LOGGEDCMD\", 1, 0))) as \"Config commands\" dc(host) as Switches values(src) as Sources by user\n| sort - \"Failed logins\" - \"Config commands\"\n| rename user as User",
                "enableSmartSources": true
            },
            "name": "CLI sessions by user"
        },
        "ds_syslog_latest": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_catalyst sourcetype=\"cisco:ios\"\n| eval sw_site=case(like(host, \"atl%\"), \"atlanta\", like(host, \"ber%\"), \"berlin\", like(host, \"vie%\"), \"vienna\")\n| search sw_site=\"$site$\" host=\"$device$\"\n| head 50\n| eval Time=strftime(_time, \"%H:%M:%S\")\n| table Time host severity mnemonic message_text\n| rename host as Switch severity as Severity mnemonic as Mnemonic message_text as Message",
                "enableSmartSources": true
            },
            "name": "Latest syslog"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
